from django.contrib.auth import get_user_model
from django.contrib.auth.password_validation import validate_password
from django.db import transaction
from rest_framework import serializers

from common.validators import validate_password_strength
from .models import UserProfile

User = get_user_model()


class RegisterSerializer(serializers.ModelSerializer):
    """ثبت‌نام کاربر جدید."""
    password = serializers.CharField(
        write_only=True,
        required=True,
        validators=[validate_password, validate_password_strength],
        style={"input_type": "password"},
    )
    password_confirm = serializers.CharField(
        write_only=True,
        required=True,
        style={"input_type": "password"},
    )

    class Meta:
        model = User
        fields = [
            "username", "email", "password", "password_confirm",
            "first_name", "last_name",
        ]
        extra_kwargs = {
            "username": {
                "error_messages": {"unique": "این نام کاربری قبلاً گرفته شده است."},
            },
            "email": {
                "error_messages": {"invalid": "فرمت ایمیل نامعتبر است."},
            },
        }

    def validate_email(self, value):
        value = value.lower().strip()
        if User.objects.filter(email__iexact=value).exists():
            raise serializers.ValidationError("این ایمیل قبلاً ثبت شده است.")
        return value

    def validate_username(self, value):
        value = value.strip()
        if User.objects.filter(username__iexact=value).exists():
            raise serializers.ValidationError("این نام کاربری قبلاً گرفته شده است.")
        return value

    def validate(self, attrs):
        if attrs["password"] != attrs["password_confirm"]:
            raise serializers.ValidationError(
                {"password_confirm": "رمزهای عبور یکسان نیستند."}
            )
        return attrs

    @transaction.atomic
    def create(self, validated_data):
        validated_data.pop("password_confirm")
        password = validated_data.pop("password")
        user = User.objects.create_user(password=password, **validated_data)
        UserProfile.objects.create(user=user)
        return user


