import re
from django.core.exceptions import ValidationError


class ComplexPasswordValidator:
    """بررسی پیچیدگی رمز عبور."""

    def __call__(self, value):
        errors = []
        if not re.search(r"[A-Z]", value):
            errors.append("حداقل یک حرف بزرگ")
        if not re.search(r"[a-z]", value):
            errors.append("حداقل یک حرف کوچک")
        if not re.search(r"\d", value):
            errors.append("حداقل یک عدد")
        if not re.search(r'[!@#$%^&*(),.?":{}|<>]', value):
            errors.append("حداقل یک کاراکتر خاص")
        if errors:
            raise ValidationError(f"رمز عبور باید شامل: {', '.join(errors)} باشد.")


validate_password_strength = ComplexPasswordValidator()

import logging
from django.contrib.auth import authenticate, get_user_model
from django.contrib.auth.tokens import default_token_generator
from django.core.mail import send_mail
from django.conf import settings
from django.utils.encoding import force_bytes, force_str
from django.utils.http import urlsafe_base64_encode, urlsafe_base64_decode
from rest_framework import generics, status
from rest_framework.permissions import AllowAny, IsAuthenticated
from rest_framework.response import Response
from rest_framework.throttling import ScopedRateThrottle
from rest_framework.views import APIView
from rest_framework_simplejwt.tokens import RefreshToken
from rest_framework_simplejwt.views import TokenObtainPairView
from rest_framework_simplejwt.exceptions import TokenError

from common.audit import SecurityAudit
from .models import UserProfile
from .serializers import (
    RegisterSerializer, UserSerializer, ProfileSerializer,
    ChangePasswordSerializer, PasswordResetRequestSerializer,
    PasswordResetConfirmSerializer, VerifyEmailSerializer,
)

logger = logging.getLogger("api.auth")
User = get_user_model()


class RegisterView(APIView):
    """ثبت‌نام کاربر جدید."""
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "register"

    def post(self, request):
        serializer = RegisterSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        user = serializer.save()

        # ساخت توکن‌ها
        refresh = RefreshToken.for_user(user)

        # Audit
        SecurityAudit.log("user.registered", user=user, request=request)

        # ارسال ایمیل تأیید (async)
        try:
            from .tasks import send_verification_email
            send_verification_email.delay(str(user.id))
        except Exception as e:
            logger.warning(f"Failed to queue verification email: {e}")

        return Response({
            "user": UserSerializer(user).data,
            "access": str(refresh.access_token),
            "refresh": str(refresh),
        }, status=status.HTTP_201_CREATED)


class LoginView(TokenObtainPairView):
    """ورود با username/password."""
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "login"

    def post(self, request, *args, **kwargs):
        username = request.data.get("username", "")
        try:
            response = super().post(request, *args, **kwargs)
        except Exception:
            SecurityAudit.log(
                "security.login.failed",
                user=None, request=request,
                attempted_username=username,
            )
            raise

        if response.status_code == 200:
            try:
                user = User.objects.get(username=username)
                SecurityAudit.log("security.login.success", user=user, request=request)
            except User.DoesNotExist:
                pass

        return response


class LogoutView(APIView):
    """خروج با blacklist کردن refresh token."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        try:
            refresh_token = request.data.get("refresh")
            if not refresh_token:
                return Response(
                    {"detail": "فیلد refresh الزامی است."},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            token = RefreshToken(refresh_token)
            token.blacklist()

            SecurityAudit.log("security.logout", user=request.user, request=request)
            return Response({"detail": "خروج موفق"}, status=status.HTTP_200_OK)

        except TokenError:
            return Response(
                {"detail": "توکن نامعتبر یا منقضی است."},
                status=status.HTTP_400_BAD_REQUEST,
            )


