class ChangePasswordView(APIView):
    """تغییر رمز عبور."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        serializer = ChangePasswordSerializer(
            data=request.data,
            context={"request": request},
        )
        serializer.is_valid(raise_exception=True)
        serializer.save()

        # Blacklist همه refresh tokenهای کاربر
        from rest_framework_simplejwt.token_blacklist.models import OutstandingToken
        OutstandingToken.objects.filter(user=request.user).delete()

        SecurityAudit.log("security.password.changed", user=request.user, request=request)

        return Response({
            "detail": "رمز عبور با موفقیت تغییر کرد. لطفاً دوباره وارد شوید."
        })


class PasswordResetRequestView(APIView):
    """درخواست بازیابی رمز عبور."""
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "password_reset"

    def post(self, request):
        serializer = PasswordResetRequestSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        email = serializer.validated_data["email"]

        # همیشه پاسخ موفق بده (جلوگیری از User Enumeration)
        success_response = Response({
            "detail": "اگر این ایمیل در سیستم ثبت شده باشد، لینک بازیابی ارسال خواهد شد."
        })

        try:
            user = User.objects.get(email__iexact=email)
        except User.DoesNotExist:
            SecurityAudit.log(
                "security.password_reset.attempted_unknown_email",
                user=None, request=request, email=email,
            )
            return success_response

        # ساخت توکن
        uid = urlsafe_base64_encode(force_bytes(user.pk))
        token = default_token_generator.make_token(user)

        reset_url = f"{settings.FRONTEND_URL}/reset-password/{uid}/{token}/"

        try:
            from .tasks import send_password_reset_email
            send_password_reset_email.delay(str(user.id), reset_url)
        except Exception as e:
            logger.error(f"Failed to queue reset email: {e}")

        SecurityAudit.log(
            "security.password_reset.requested",
            user=user, request=request,
        )

        return success_response


class PasswordResetConfirmView(APIView):
    """تأیید بازیابی رمز عبور."""
    permission_classes = [AllowAny]

    def post(self, request):
        serializer = PasswordResetConfirmSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        try:
            uid = force_str(urlsafe_base64_decode(serializer.validated_data["uid"]))
            user = User.objects.get(pk=uid)
        except (User.DoesNotExist, ValueError, TypeError, OverflowError):
            return Response(
                {"detail": "لینک بازیابی نامعتبر است."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        if not default_token_generator.check_token(user, serializer.validated_data["token"]):
            return Response(
                {"detail": "توکن نامعتبر یا منقضی است."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        user.set_password(serializer.validated_data["new_password"])
        user.save(update_fields=["password"])

        # Blacklist همه توکن‌های قبلی
        from rest_framework_simplejwt.token_blacklist.models import OutstandingToken
        OutstandingToken.objects.filter(user=user).delete()

        SecurityAudit.log(
            "security.password_reset.completed",
            user=user, request=request,
        )

        return Response({"detail": "رمز عبور با موفقیت بازیابی شد."})


class VerifyEmailView(APIView):
    """تأیید ایمیل."""
    permission_classes = [AllowAny]

    def post(self, request):
        serializer = VerifyEmailSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        try:
            uid = force_str(urlsafe_base64_decode(serializer.validated_data["uid"]))
            user = User.objects.get(pk=uid)
        except (User.DoesNotExist, ValueError, TypeError, OverflowError):
            return Response(
                {"detail": "لینک تأیید نامعتبر است."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        if user.is_email_verified:
            return Response({"detail": "ایمیل قبلاً تأیید شده است."})

        if not default_token_generator.check_token(user, serializer.validated_data["token"]):
            return Response(
                {"detail": "توکن نامعتبر یا منقضی است."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        user.is_email_verified = True
        user.save(update_fields=["is_email_verified"])

        SecurityAudit.log("user.email.verified", user=user, request=request)

        return Response({"detail": "ایمیل با موفقیت تأیید شد."})

import pytest
from django.contrib.auth import get_user_model
