@pytest.mark.django_db
class TestMe:
    url = reverse("users:me")

    def test_me_requires_auth(self, api_client):
        response = api_client.get(self.url)
        assert response.status_code == status.HTTP_401_UNAUTHORIZED

    def test_me_returns_user(self, api_client):
        user = User.objects.create_user(username="sara", password="S3cret!Pass")
        api_client.force_authenticate(user=user)
        response = api_client.get(self.url)
        assert response.status_code == status.HTTP_200_OK
        assert response.data["username"] == "sara"

    def test_me_update(self, api_client):
        user = User.objects.create_user(username="sara", password="S3cret!Pass")
        api_client.force_authenticate(user=user)
        response = api_client.patch(self.url, {"first_name": "Sara"}, format="json")
        assert response.status_code == status.HTTP_200_OK
        user.refresh_from_db()
        assert user.first_name == "Sara"


